const config = $('Set Campaign Config').first().json;
const input = $input.first();
const payload = input.json || {};

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    const next = text[i + 1];

    if (inQuotes) {
      if (char === '"' && next === '"') {
        cell += '"';
        i += 1;
      } else if (char === '"') {
        inQuotes = false;
      } else {
        cell += char;
      }
      continue;
    }

    if (char === '"') {
      inQuotes = true;
    } else if (char === ',') {
      row.push(cell);
      cell = '';
    } else if (char === '\n') {
      row.push(cell);
      rows.push(row);
      row = [];
      cell = '';
    } else if (char !== '\r') {
      cell += char;
    }
  }

  if (cell !== '' || row.length > 0) {
    row.push(cell);
    rows.push(row);
  }

  return rows;
}

function normalizePhone(value) {
  const digits = String(value || '').replace(/\D+/g, '');
  if (!digits) return null;
  if (digits.startsWith('593') && digits.length >= 12) return digits;
  if (digits.startsWith('09') && digits.length === 10) return '593' + digits.slice(1);
  if (digits.length === 9 && digits.startsWith('9')) return '593' + digits;
  if (digits.length === 10 && digits.startsWith('9')) return '593' + digits.slice(1);
  if (digits.length === 12 && digits.startsWith('593')) return digits;
  return digits;
}

function pickDisplayName(fullName) {
  const clean = String(fullName || '').trim().replace(/\s+/g, ' ');
  if (!clean) return 'Cliente Hyundai';
  return clean.split(' ')[0];
}

const csvText = typeof payload.data === 'string'
  ? payload.data
  : typeof payload.body === 'string'
    ? payload.body
    : typeof payload.response === 'string'
      ? payload.response
      : typeof payload.raw === 'string'
        ? payload.raw
        : '';

if (!csvText) {
  throw new Error('No se encontro texto CSV en la respuesta del nodo Fetch Source CSV');
}

const rows = parseCsv(csvText);
if (!rows.length) {
  throw new Error('La base CSV esta vacia');
}

const headers = rows[0].map((value) => String(value || '').trim());
const dataRows = rows.slice(1);

const contacts = dataRows.map((values) => {
  const record = {};
  headers.forEach((header, index) => {
    if (!header) return;
    record[header] = values[index] ?? '';
  });

  const brand = String(record.brand || '').trim();
  const model = String(record.model || brand).trim();

  return {
    name: String(record.name || '').trim(),
    phone: String(record.phone_number || record['phone number'] || '').trim(),
    brand,
    model,
    email: '',
    city: '',
    advisor: '',
    salesPoint: '',
    idNumber: '',
    chassis: '',
  };
});

const deduped = [];
const seen = new Set();

for (const contact of contacts) {
  const phone = normalizePhone(contact.phone);
  if (!phone || seen.has(phone)) continue;
  seen.add(phone);
  deduped.push({
    ...contact,
    whatsapp_to: phone,
    displayName: pickDisplayName(contact.name),
  });
}

const fallbackContact = {
  name: 'Cliente Hyundai',
  displayName: 'Cliente Hyundai',
  whatsapp_to: normalizePhone(config.testNumber),
  brand: '',
  model: '',
  email: '',
  city: '',
  advisor: '',
  salesPoint: '',
  idNumber: '',
  chassis: '',
  source: 'fallback-test-number',
};

const recipients = config.testMode
  ? [{
      ...(deduped[0] || fallbackContact),
      whatsapp_to: normalizePhone(config.testNumber),
      source: 'test-number',
    }]
  : deduped;

return recipients.map((contact, index) => ({
  json: {
    campaignName: config.campaignName,
    templateName: config.templateName,
    languageCode: config.languageCode,
    drawDate: config.drawDate,
    drawTime: config.drawTime,
    sourceSheet: config.sourceSheet,
    sourceSheetUrl: config.sourceSheetUrl,
    sourceCsvUrl: config.sourceCsvUrl,
    testMode: config.testMode,
    accountId: config.accountId,
    inboxId: config.inboxId,
    headerImageUrl: config.headerImageUrl,
    contact,
    recipientIndex: index + 1,
    totalRecipients: recipients.length,
  },
}));

return $input.all().map((item) => {
  const row = item.json;
  return {
    json: {
      ...row,
      payload: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: row.contact.whatsapp_to,
        type: 'template',
        template: {
          name: row.templateName,
          language: {
            code: row.languageCode,
          },
          components: [
            {
              type: 'header',
              parameters: [
                {
                  type: 'image',
                  image: {
                    link: row.headerImageUrl,
                  },
                },
              ],
            },
            {
              type: 'body',
              parameters: [
                { type: 'text', text: row.contact.displayName || 'Cliente Hyundai' },
                { type: 'text', text: row.contact.model || row.contact.brand || 'vehiculo' },
              ],
            },
          ],
        },
      },
    },
  };
});

const rows = $input.all().map((item) => item.json);
return [{
  json: {
    campaignName: rows[0]?.campaignName || 'CAMPANA RECORDATORIO MANTENIMIENTO JUNIO 2026',
    sentItems: rows.length,
    testMode: rows[0]?.testMode ?? true,
    recipients: rows.map((row) => ({
      to: row.contact?.whatsapp_to || null,
      name: row.contact?.displayName || row.contact?.name || null,
      messageId: row.messages?.[0]?.id || null,
    })),
  },
}];
